					isToday ? "font-semibold text-text" : "text-faint",
				)}
			>
				{day}
			</span>
		</div>
	);
}

function HabitRow({ habit, onToggle, onOpen }: { habit: Habit; onToggle: () => void; onOpen: () => void }) {
	return (
		<div
			onClick={onOpen}
			className="flex cursor-pointer items-center gap-3.5 rounded-[18px] border border-line/70 bg-surface px-3.5 py-3.5"
		>
			<div
				className="grid h-11 w-11 shrink-0 place-items-center rounded-[14px]"
				style={{ backgroundColor: `${habit.color}1f`, color: habit.color }}
			>
				<Icon name={habit.icon} size={21} />
			</div>

			<div className="min-w-0 flex-1">
				<p className={cn("truncate text-[15px] font-medium", habit.done && "text-muted")}>{habit.name}</p>
				<p className="mt-0.5 flex items-center gap-1 text-[12.5px] text-faint">
					{!habit.done && <Icon name="flame" size={12} strokeWidth={2.1} className="shrink-0 text-flame" />}
					<span className="truncate">{subtitle(habit)}</span>
				</p>
			</div>

			<button
				aria-label={habit.done ? `${habit.name} klar, tryck för att ångra` : `Markera ${habit.name} som klar`}
				onClick={(e) => {
					e.stopPropagation();
					onToggle();
				}}
				className="grid h-7 w-7 shrink-0 place-items-center rounded-full border-2"
				style={
					habit.done
						? { backgroundColor: habit.color, borderColor: habit.color, color: "#08080b" }
						: { borderColor: "#35353f" }
				}
			>
				{habit.done && <Icon name="check" size={13} strokeWidth={3.2} />}
			</button>
		</div>
	);
}

export default function Home() {
	ui.use();
	ui.state.habits ??= HABITS;
	ui.state.user ??= "Elsa";

	const habits = ui.state.habits as Habit[];
	const done = habits.filter((h) => h.done);
	const pending = habits.filter((h) => !h.done);
	const week = weekAhead();

	const toggle = (id: string) => {
		ui.state.habits = habits.map((h) => (h.id === id ? markToday(h, !h.done) : h));
	};
	const open = (id: string) => ui.go("habit-detail", { selected: id });

	return (
		<div className="flex h-full flex-col bg-ink text-text">
			<StatusBar time="09:12" />

			<header className="shrink-0 px-5 pt-1 pb-4">
				<h1 className="text-[27px] font-semibold leading-tight tracking-[-0.025em]">
					{ui.state.greeting ?? "God morgon"}, {ui.state.user}
				</h1>
				<p className="mt-1 text-[14px] text-muted">{ui.state.date ?? "Måndag 27 juli"}</p>
			</header>

			<section className="mx-5 shrink-0 rounded-card border border-line/70 bg-surface px-4 py-4">
				<div className="flex items-baseline justify-between">
					<span className="text-[13px] text-muted">Vecka {ui.state.week ?? 31}</span>
					<span className="text-[13px] font-medium">
						{done.length === 0 ? "Inget klart än" : `${done.length} av ${habits.length} klara`}
					</span>
				</div>
				<div className="mt-3 flex justify-between">
					{week.map((d) => (
						<div key={d.index} className="flex flex-col items-center gap-1.5">
							<span className={cn("text-[11px]", d.isToday ? "font-medium text-flame" : "text-faint")}>
								{d.letter}
							</span>
							<DayRing day={d.day} pct={doneOn(habits, d.index) / habits.length} isToday={d.isToday} />
						</div>
					))}
				</div>
			</section>

			<div className="min-h-0 flex-1 overflow-y-auto px-5 pt-4">
				{pending.length > 0 && (
					<>
						<h2 className="pb-2 text-[13px] text-muted">Kvar idag</h2>
						<div className="flex flex-col gap-2.5">
							{pending.map((h) => (
								<HabitRow key={h.id} habit={h} onToggle={() => toggle(h.id)} onOpen={() => open(h.id)} />
							))}
						</div>
					</>
				)}

				{done.length > 0 && (
					<>
						<h2 className={cn("pb-2.5 text-[13px] text-muted", pending.length > 0 && "pt-5")}>Klart idag</h2>
						<div className="flex flex-col gap-2.5">
							{done.map((h) => (
								<HabitRow key={h.id} habit={h} onToggle={() => toggle(h.id)} onOpen={() => open(h.id)} />
							))}
						</div>
					</>
				)}

				{pending.length === 0 && (
					<p className="pt-4 text-center text-[13px] text-muted">Allt klart för idag.</p>
				)}
			</div>

			<div className="shrink-0">
				<div className="h-6 bg-gradient-to-t from-ink to-transparent" />
				<div className="px-5 pb-2">
					<button
						data-go="add-habit"
						data-transition="modal"
						aria-label="Lägg till ny vana"
						className="flex h-[52px] w-full items-center justify-center gap-2 rounded-full bg-flame text-[16px] font-semibold text-ink"
					>
						<Icon name="plus" size={19} strokeWidth={2.6} />
						Ny vana
					</button>
				</div>
				<div className="mx-auto mt-2 mb-2 h-[5px] w-[134px] rounded-full bg-white/25" />
			</div>
		</div>
	);
}
